/*! jQuery stand-in for the Records Desk fixture: the $ factory plus ready, on, text and each. Not jQuery. */
(function (w) {
  function Q(els) { this.length = els.length; for (var i = 0; i < els.length; i++) this[i] = els[i] }
  Q.prototype.each = function (fn) { for (var i = 0; i < this.length; i++) fn.call(this[i], i, this[i]); return this }
  Q.prototype.ready = function (fn) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn); else fn()
    return this
  }
  Q.prototype.on = function (type, fn) { return this.each(function () { this.addEventListener(type, fn) }) }
  Q.prototype.text = function (s) { return this.each(function () { this.textContent = s }) }
  function $(sel) {
    if (typeof sel === 'function') return new Q([document]).ready(sel)
    if (typeof sel === 'string') return new Q(document.querySelectorAll(sel))
    return new Q(sel ? [sel] : [])
  }
  $.fn = Q.prototype
  w.$ = w.jQuery = $
})(window);
